.fig2 th{color:inherit!important;opacity:.85}
@media (prefers-color-scheme:light){a.rt em.late{color:#9a4434}}
.ph .lb{white-space:nowrap;font-size:11px}
.gl1,.rtd small,.gm,.gc,.ex-c,.mo li,.gi span,.bwn,.sum li,.rg p,.mo p{text-wrap:pretty}
.pr3{grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))!important}
.kcols{grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr))!important}
.t.off .cn,.t.off em.n{opacity:1!important;color:#a3a3a3!important}
.stk .s-f{background:#6b6862}
.gl1 b{display:block;margin-bottom:2px}.gl1 .tm{display:block;padding:1px 0}.gl1 .tm+.tm::before{content:none}
.ph .lb{white-space:nowrap;font-size:10px;padding:0 3px;left:2px;bottom:2px;max-width:calc(100% - 4px)}/* 좋아지는 것: 펼치면 요약 줄 숨김(목록 첫 줄과 겹침) */

.gd>details[open]>summary .g1{display:none}
.gd>details[open]>summary{justify-content:flex-end}
.gd>details[open]>summary .gn{margin-left:auto}.gd>details[open]>summary::after{margin-left:8px}
.seatfig{max-width:290px!important;margin:6px auto!important}.seatfig svg{width:100%;height:auto;display:block;margin:0 auto}

details.fab{display:none!important}
nav,.side,nav.chipnav,.side,.scroll::before{position:relative!important;top:auto!important}
